{"path": "units/rules/engine.py", "content": "def evaluate(rules, facts):
    """规则求值。

    - {"all": [k, ...]}：所有 k 在 facts 中为真才返回 True（空列表为 True）。
    - {"any": [k, ...]}：任一 k 为真即返回 True（空列表为 False）。
    - 缺少某个 key 视为 False；无法识别的规则返回 False。
    """
    if "all" in rules:
        return all(bool(facts.get(key, False)) for key in rules["all"])
    if "any" in rules:
        return any(bool(facts.get(key, False)) for key in rules["any"])
    return False
"}

{"path": "units/ledger/ledger.py", "content": """"一个只关心单个账户的小账本。"""


class Ledger:
    def apply(self, rows, op):
        """rows 是 [(kind, account, cents), ...]，返回**该账户**的行（保持原顺序）。

        - kind 只有 "deposit" 与 "withdraw"。
        - 任一行的金额为负时抛 ValueError。
        """
        result = []
        for kind, account, cents in rows:
            if cents < 0:
                raise ValueError("amount must be non-negative: %r" % (cents,))
            if account == op:
                result.append((kind, account, cents))
        return result


def balance(rows, account):
    """返回该账户的净额：deposit 相加、withdraw 相减；没有该账户的行时返回 0。"""
    net = 0
    for kind, acct, cents in rows:
        if acct != account:
            continue
        if kind == "deposit":
            net += cents
        elif kind == "withdraw":
            net -= cents
    return net
"}

{"path": "units/schedule/schedule.py", "content": """"闭区间的时间段工具。"""


def slots(ranges, minutes):
    """合并闭区间：两段之间的空隙（next_lo - prev_hi）小于 minutes 视为同一段。

    返回按起点升序的合并结果；空输入返回 []。
    """
    if not ranges:
        return []
    ordered = sorted((tuple(r) for r in ranges), key=lambda r: (r[0], r[1]))
    result = [ordered[0]]
    for lo, hi in ordered[1:]:
        prev_lo, prev_hi = result[-1]
        if lo - prev_hi < minutes:
            result[-1] = (prev_lo, max(prev_hi, hi))
        else:
            result.append((lo, hi))
    return result


def overlaps(a, b):
    """两个闭区间是否有交叠；端点正好相接（如 (0,10) 与 (10,20)）不算交叠。"""
    return a[0] < b[1] and b[0] < a[1]
"}

{"path": "units/intervals/intervals.py", "content": """"闭区间工具（整数端点，lo <= hi）。"""


class Impl:
    def merge(self, ranges, gap=0):
        """合并闭区间。

        按 lo 升序排序后，若相邻两段之间**缺失的整数个数**
        （next.lo - prev.hi - 1）小于等于 gap 就合并。
        返回 [(lo, hi), ...] 升序；空输入返回 []。
        """
        if not ranges:
            return []
        ordered = sorted((tuple(r) for r in ranges), key=lambda r: (r[0], r[1]))
        result = [ordered[0]]
        for lo, hi in ordered[1:]:
            prev_lo, prev_hi = result[-1]
            if lo - prev_hi - 1 <= gap:
                result[-1] = (prev_lo, max(prev_hi, hi))
            else:
                result.append((lo, hi))
        return result

    def subtract(self, ranges, hole):
        """从 ranges 中挖去闭区间 hole：返回剩下的闭区间（升序）。

        与 hole 不相交的段原样保留，被完全覆盖的段消失，横跨 hole 的段分裂成两段。
        输入会先做一次 merge 归一化。
        """
        hlo, hhi = hole
        result = []
        for lo, hi in self.merge(ranges):
            if hhi < lo or hlo > hi:
                result.append((lo, hi))
                continue
            if lo < hlo:
                result.append((lo, hlo - 1))
            if hi > hhi:
                result.append((hhi + 1, hi))
        return result

    def total_length(self, ranges):
        """ranges 覆盖的整数个数之和（闭区间含端点；重叠只算一次）。"""
        return sum(hi - lo + 1 for lo, hi in self.merge(ranges))
"}

{"path": "units/flags/flags.py", "content": """"命令行风格的参数解析。"""


class Impl:
    def parse(self, argv):
        """返回 {"values": {...}, "flags": {...}, "positional": [...]}。

        - 不以 "-" 开头、或正好是 "-" 的项，按出现顺序进 positional。
        - `--` 之后的所有项都是位置参数（`--` 自己不出现在结果里）。
        - `--key=value` 与 `--key value` 都是键值对，键是 key。
        - `--key` 后面没有可用值（到结尾，或后面紧跟另一个 "--" 开头的项）时它是开关。
        - `-abc` 是三个开关 a、b、c。
        - values 的每个值是**列表**，重复的键按出现顺序累积；开关重复出现仍是 True。
        """
        values = {}
        flags = {}
        positional = []
        i = 0
        n = len(argv)
        while i < n:
            token = argv[i]
            if token == "--":
                positional.extend(argv[i + 1:])
                break
            if token.startswith("--"):
                body = token[2:]
                if "=" in body:
                    key, value = body.split("=", 1)
                    values.setdefault(key, []).append(value)
                else:
                    key = body
                    if i + 1 < n and not argv[i + 1].startswith("--"):
                        values.setdefault(key, []).append(argv[i + 1])
                        i += 1
                    else:
                        flags[key] = True
            elif token.startswith("-") and token != "-":
                for ch in token[1:]:
                    flags[ch] = True
            else:
                positional.append(token)
            i += 1
        return {"values": values, "flags": flags, "positional": positional}
"}

{"path": "units/measure/measure.py", "content": "class Impl:
    _FACTORS = {"m": 100, "cm": 1, "mm": 0.1}

    def to_cm(self, value, unit):
        """把 value（unit 单位）换算成厘米；unit 只支持 m/cm/mm，否则抛 ValueError。"""
        try:
            factor = self._FACTORS[unit]
        except (KeyError, TypeError):
            raise ValueError("unknown unit: %r" % (unit,))
        return value * factor
"}

{"path": "units/slugify/slugify.py", "content": "class Impl:
    def slugify(self, text):
        """小写化、把连续的非字母数字折叠成单个 "-"、去掉首尾 "-"，空结果返回 "untitled"。"""
        out = []
        prev_dash = False
        for ch in text.lower():
            if ch.isalnum():
                out.append(ch)
                prev_dash = False
            elif out and not prev_dash:
                out.append("-")
                prev_dash = True
        slug = "".join(out).strip("-")
        return slug or "untitled"
"}

{"path": "units/ranges/ranges.py", "content": "class Impl:
    def merge(self, ranges):
        """合并闭区间，返回按起点排序的元组列表（空输入返回 []）。

        相邻两段只要有交叠（next.lo <= prev.hi）就合并。
        """
        if not ranges:
            return []
        ordered = sorted((tuple(r) for r in ranges), key=lambda r: (r[0], r[1]))
        result = [ordered[0]]
        for lo, hi in ordered[1:]:
            prev_lo, prev_hi = result[-1]
            if lo <= prev_hi:
                result[-1] = (prev_lo, max(prev_hi, hi))
            else:
                result.append((lo, hi))
        return result
