{"path": "units/chain/stage1.py", "content": "import csv


def parse_orders(path):
    """读取表头为 id,qty,price 的 CSV，返回按文件顺序排列的 dict 列表（值转为 int）。"""
    rows = []
    with open(path, newline="") as handle:
        for row in csv.DictReader(handle):
            rows.append({
                "id": int(row["id"]),
                "qty": int(row["qty"]),
                "price": int(row["price"]),
            })
    return rows
"}

{"path": "units/chain/stage3.py", "content": "def total_by_price(rows):
    """按 price 汇总 qty，返回 {price: 总 qty}。"""
    totals = {}
    for row in rows:
        totals[row["price"]] = totals.get(row["price"], 0) + row["qty"]
    return totals
